function CountChar(s: string, c: char): int
    reads s
{
    var count := 0;
    foreach i in 0 .. s.Length - 1 {
        if s[i] == c {
            count := count + 1;
        }
    }
    count
}

function CountDistinctChars(s: string): int
    reads s
{
    var distinctCount := 0;
    var seen := Set<char>();
    foreach i in 0 .. s.Length - 1 {
        if !seen.Contains(s[i]) {
            seen := seen.Add(s[i]);
            distinctCount := distinctCount + 1;
        }
    }
    distinctCount
}
